#!/usr/bin/env python3
"""Compact five-stage progression at authored print size, with an external feedback edge.
Fixed geometry keeps the feedback outside the vertical flow and matches editable SVG/native.
"""
from pathlib import Path
from html import escape
R=Path(__file__).resolve().parents[3]
W,H=315,228
# id,x,y,width,height, heading, explanatory lines
stages=[
 ('question',84,2,175,21,'Engineering question',[]),
 ('model',35,33,273,48,'Model and define properties',['Representations: state machines · dependency graphs','Properties: legal transitions · permitted dependencies']),
 ('analysis',35,91,273,48,'Analyze the modeled properties',['State exploration · model checking · simulation','Constraint solving · static analysis']),
 ('evidence',73,149,197,21,'Interpret the evidence',[]),
 ('decisions',35,180,273,44,'Make engineering decisions',['Refine architecture and design','Choose which obligations warrant enforcement']),
]
alt='Five stages: Engineering question; Model and define properties; Analyze the modeled properties; Interpret the evidence; Make engineering decisions. The model stage names state machines and dependency graphs, with legal transitions and permitted dependencies. Analyses include state exploration, model checking, simulation, constraint solving, and static analysis. Decisions refine architecture and design and select obligations for enforcement. A feedback arrow returns from decisions to revise the model and properties.'
svg=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}pt" height="{H}pt" viewBox="0 0 {W} {H}" role="img" aria-labelledby="qapTitle qapDesc">','<title id="qapTitle">From engineering question to engineering consequence</title>',f'<desc id="qapDesc">{escape(alt)}</desc>','<rect width="315" height="228" fill="white"/>','<defs><marker id="arrow" viewBox="0 0 6 6" refX="5.6" refY="3" markerWidth="4.5" markerHeight="4.5" orient="auto" markerUnits="userSpaceOnUse"><path d="M0 0L6 3L0 6Z" fill="#57534e"/></marker></defs>']
tex=[r'% Generated by book/figures/question-to-consequence/generate.py; authored at 315bp width.',r'\begin{tikzpicture}[x=1bp,y=-1bp,font=\magefigurefont\fontsize{10}{12}\selectfont,>=Stealth]',r'\path[use as bounding box] (0,0) rectangle (315,228);']
def text(x,y,s,bold=False,rotate=False):
 tr=f' transform="rotate(-90 {x} {y})"'if rotate else''
 svg.append(f'<text x="{x}" y="{y}" text-anchor="middle" font-family="Source Sans 3" font-size="10" fill="#1c1917"'+(' font-weight="700"'if bold else'')+tr+'>'+escape(s)+'</text>')
 tex.append(r'\node[anchor=base,inner sep=0bp,outer sep=0bp'+(',rotate=90'if rotate else'')+(',font=\\magefigurefont\\fontsize{10}{12}\\selectfont\\bfseries'if bold else'')+'] at ('+str(x)+','+str(y)+') {'+s+'};')
for key,x,y,w,h,head,lines in stages:
 fill='#e7edf3'if key=='model'else'#f6f4ef';stroke='#2f5169'if key=='model'else'#57534e'
 svg.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="2.5" fill="{fill}" stroke="{stroke}" stroke-width=".65"/>')
 tex.append(r'\draw[rounded corners=2.5bp,fill=white,line width=.65bp] ('+str(x)+','+str(y)+') rectangle ('+str(x+w)+','+str(y+h)+');')
 text(x+w/2,y+14,head,True)
 for j,line in enumerate(lines):text(x+w/2,y+27+j*12,line)
for a,b in zip(stages,stages[1:]):
 x=171.5;y1=a[2]+a[4];y2=b[2]
 svg.append(f'<path d="M{x} {y1}V{y2}" fill="none" stroke="#57534e" stroke-width=".65" marker-end="url(#arrow)"/>')
 tex.append(r'\draw[-{Stealth[length=4.5bp,width=3.5bp]},line width=.65bp] ('+str(x)+','+str(y1)+')--('+str(x)+','+str(y2)+');')
svg.append('<path d="M35 202H24V57H35" fill="none" stroke="#57534e" stroke-width=".65" marker-end="url(#arrow)"/>')
tex.append(r'\draw[-{Stealth[length=4.5bp,width=3.5bp]},line width=.65bp] (35,202)--(24,202)--(24,57)--(35,57);')
text(12,129.5,'Revise model and properties',rotate=True)
svg.append('</svg>');tex.append(r'\end{tikzpicture}')
(R/'book/assets/question-to-consequence-progression.svg').write_text('\n'.join(svg)+'\n')
(R/'book/tikz/figures/question-to-consequence-progression.tex').write_text('\n'.join(tex)+'\n')
